<?php require __DIR__.'/../includes/auth.php';$s=db()->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC');$s->execute([user()['id']]);$rows=$s->fetchAll();db()->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([user()['id']]);$pageTitle='Notifications';require __DIR__.'/../includes/header.php';?><h1>Notifications</h1><div class="panel"><?php foreach($rows as $r):?><article><h3><?=e($r['title'])?></h3><p><?=e($r['message'])?></p><p class="muted"><?=e($r['created_at'])?></p></article><?php endforeach;?><?php if(!$rows):?><p>No notifications yet.</p><?php endif;?></div><?php require __DIR__.'/../includes/footer.php'; ?>
